import React from "react";
import { Link } from "react-router-dom";
// If you have a Navbar.css file, keep this import! If not, you can delete it.


const Navbar = () => {
  return (
    <nav className="navbar">

      {/* The Logo also acts as a Home button */}
      <div className="logo">
        <Link to="/" style={{ color: "white", textDecoration: "none" }}>
          🌊 Garbage Detection
        </Link>
      </div>

      {/* Navigation Links */}
      <ul className="nav-links" style={{ display: "flex", gap: "20px", listStyle: "none" }}>
        <li>
          <Link to="/" style={{ color: "white", textDecoration: "none" }}>Home</Link>
        </li>
        <li>
          {/* Currently, your Upload feature is on the Home page ("/") in App.js */}
          <Link to="/" style={{ color: "white", textDecoration: "none" }}>Upload</Link>
        </li>
        <li>
          <Link to="/about" style={{ color: "white", textDecoration: "none" }}>About</Link>
        </li>
      </ul>

    </nav>
  );
};

export default Navbar;
